package reliquary.item;

import com.google.common.collect.ImmutableMap;
import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.DynamicOps;
import com.mojang.serialization.codecs.PrimitiveCodec;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.ExtraCodecs;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import reliquary.init.ModDataComponents;
import reliquary.item.component.OversizedComponentItemHandler;
import reliquary.util.InventoryHelper;

import javax.annotation.Nullable;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;

public abstract class ChargeableItem extends ToggleableItem {
	public static final PrimitiveCodec<Integer> STRING_ENCODED_INT = new PrimitiveCodec<>() {
		@Override
		public <T> DataResult<Integer> read(final DynamicOps<T> ops, final T input) {
			return ops.getStringValue(input).map(s -> {
				if (s.startsWith("i")) {
					return Integer.parseInt(s.substring(1));
				} else {
					return Integer.parseInt(s);
				}
			});
		}

		@Override
		public <T> T write(final DynamicOps<T> ops, final Integer value) {
			return ops.createString("i" + value);
		}

		@Override
		public String toString() {
			return "Int";
		}
	};

	public static final Codec<Map<Integer, Integer>> PARTIAL_CHARGES_CODEC = Codec.unboundedMap(STRING_ENCODED_INT, ExtraCodecs.NON_NEGATIVE_INT);
	private static final int MAX_PARTIAL_CHARGES = 64;

	public static final StreamCodec<FriendlyByteBuf, Map<Integer, Integer>> PARTIAL_CHARGES_STREAM_CODEC = ByteBufCodecs.map(HashMap::new, ByteBufCodecs.INT,
			ByteBufCodecs.INT, MAX_PARTIAL_CHARGES);

	protected static final int FIRST_SLOT = 0;

	protected ChargeableItem(Properties properties, Supplier<Boolean> isDisabled) {
		super(properties, isDisabled);
	}

	protected ChargeableItem(Properties properties) {
		this(properties, () -> false);
	}

	protected <T> T getFromHandler(ItemStack stack, Function<OversizedComponentItemHandler, T> getter) {
		return getter.apply(createHandler(stack));
	}

	protected void runOnHandler(ItemStack stack, Consumer<OversizedComponentItemHandler> runner) {
		runner.accept(createHandler(stack));
	}

	public OversizedComponentItemHandler createHandler(ItemStack containerStack) {
		int size = Math.max(containerStack.has(ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS)
				? containerStack.get(ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS).getSlots()
				: getContainerInitialSize(), getContainerInitialSize());
		return new OversizedComponentItemHandler(containerStack, ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS.get(), size, this::getContainerSlotLimit,
				(slot, stack) -> isItemValidForContainerSlot(containerStack, slot, stack));
	}

	protected int getSlotWorth(int slot) {
		return 1;
	}

	protected void removeContainerContents(ItemStack stack) {
		stack.remove(ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS);
	}

	protected int getContainerInitialSize() {
		return 1;
	}

	protected int getContainerSlotLimit(ItemStack stack, int slot) {
		return getContainerSlotLimit(slot);
	}

	protected int getContainerSlotLimit(int slot) {
		return 64;
	}

	protected abstract boolean isItemValidForContainerSlot(ItemStack containerStack, int slot, ItemStack stack);

	protected void consumeAndCharge(ItemStack containerStack, int slot, Player player, int freeCapacity, int chargePerItem, int maxCount) {
		Predicate<ItemStack> isValidStack = stack -> isItemValidForContainerSlot(containerStack, slot, stack);
		consumeAndCharge(containerStack, slot, player, freeCapacity, chargePerItem, maxCount, isValidStack);
	}

	protected void consumeAndCharge(ItemStack containerStack, int slot, Player player, int freeCapacity, int chargePerItem, int maxCount,
			Predicate<ItemStack> itemMatches) {
		int maximumToConsume = Math.min(freeCapacity / chargePerItem, maxCount);
		if (maximumToConsume == 0) {
			return;
		}
		ItemStack consumedStack = InventoryHelper.consumeItemStack(itemMatches, player, maximumToConsume);
		if (consumedStack.getCount() > 0) {
			addStoredCharge(containerStack, slot, consumedStack.getCount() * chargePerItem, consumedStack);
			if (!containerStack.has(ModDataComponents.PARTIAL_CHARGES)) {
				HashMap<Integer, Integer> charges = new HashMap<>();
				charges.put(slot, 0);
				setPartialCharges(containerStack, charges);
			}
		}
	}

	private int getPartialCharge(ItemStack containerStack, int slot) {
		Map<Integer, Integer> charges = containerStack.get(ModDataComponents.PARTIAL_CHARGES);
		if (charges != null) {
			return charges.getOrDefault(slot, 0);
		}
		return 0;
	}

	public int getTotalCharge(ItemStack containerStack) {
		return getTotalCharge(containerStack, FIRST_SLOT);
	}

	public int getTotalCharge(ItemStack containerStack, int slot) {
		long totalCharge = (long) getMigratedStoredCharge(containerStack, slot) * getSlotWorth(slot) + getPartialCharge(containerStack, slot);
		return (int) Math.min(totalCharge, Integer.MAX_VALUE);
	}

	private void setPartialCharge(ItemStack containerStack, int slot, int charge) {
		Map<Integer, Integer> charges = containerStack.get(ModDataComponents.PARTIAL_CHARGES);
		charges = charges != null ? new HashMap<>(charges) : new HashMap<>();
		charges.put(slot, charge);
		setPartialCharges(containerStack, charges);
	}

	private void removePartialCharge(ItemStack containerStack, int slot) {
		Map<Integer, Integer> charges = containerStack.get(ModDataComponents.PARTIAL_CHARGES);
		if (charges != null && charges.containsKey(slot)) {
			charges = new HashMap<>(charges);
			charges.remove(slot);
			setPartialCharges(containerStack, charges);
		}
	}

	protected boolean addPartialCharge(ItemStack containerStack, int slot, int chargeToAdd, int pointLimit, ItemStack chargeStack) {
		int worth = getSlotWorth(slot);
		int storedCharge = getMigratedStoredCharge(containerStack, slot);
		int currentCharge = getPartialCharge(containerStack, slot);
		long totalCharge = (long) storedCharge * worth + currentCharge;
		int remainingCapacity = Math.toIntExact(Math.max(pointLimit - totalCharge, 0));
		int acceptedCharge = Math.min(Math.max(chargeToAdd, 0), remainingCapacity);
		int updatedPartialCharge = currentCharge + acceptedCharge;
		if (updatedPartialCharge >= worth) {
			int maxPhysicalCharge = pointLimit / worth;
			int fullCharges = Math.min(updatedPartialCharge / worth, Math.max(maxPhysicalCharge - storedCharge, 0));
			if (fullCharges > 0) {
				ItemStack storedChargeStack = chargeStack.copy();
				storedChargeStack.setCount(fullCharges);
				addStoredCharge(containerStack, slot, fullCharges, storedChargeStack);
				updatedPartialCharge -= fullCharges * worth;
			}
		}
		setPartialCharge(containerStack, slot, updatedPartialCharge);
		return acceptedCharge > 0;
	}

	private void setPartialCharges(ItemStack containerStack, Map<Integer, Integer> charges) {
		containerStack.set(ModDataComponents.PARTIAL_CHARGES, ImmutableMap.copyOf(charges));
	}

	public abstract void addStoredCharge(ItemStack containerStack, int slot, int chargeToAdd, @Nullable ItemStack chargeStack);

	protected void extractStoredCharge(ItemStack containerStack, int slot, int chargeToExtract) {
		addStoredCharge(containerStack, slot, -chargeToExtract, null);
	}

	protected int getMigratedStoredCharge(ItemStack containerStack, int slot) {
		if (!containerStack.has(ModDataComponents.PARTIAL_CHARGES)) {
			migrateLegacyChargeData(containerStack);
		}

		return getStoredCharge(containerStack, slot);
	}

	public abstract int getStoredCharge(ItemStack containerStack, int slot);

	protected boolean removeSlotWhenEmpty(int slot) {
		return false;
	}

	protected void removeSlot(ItemStack containerStack, int slot) {
		// noop
	}

	private void migrateLegacyChargeData(ItemStack containerStack) {
		Map<Integer, Integer> charges = new HashMap<>();
		int slots = createHandler(containerStack).getSlots();
		for (int slot = 0; slot < slots; slot++) {
			int worth = getSlotWorth(slot);
			int storedCharge = getStoredCharge(containerStack, slot);
			if (storedCharge <= 0 || worth <= 1) {
				continue;
			}

			int physicalCharge = storedCharge / worth;
			extractStoredCharge(containerStack, slot, storedCharge - physicalCharge);
			int partialCharge = storedCharge % worth;
			if (partialCharge > 0) {
				charges.put(slot, partialCharge);
			}
		}
		setPartialCharges(containerStack, charges);
	}

	public boolean useCharge(ItemStack containerStack, int chargeToUse) {
		return useCharge(containerStack, FIRST_SLOT, chargeToUse);
	}

	public boolean useCharge(ItemStack containerStack, int slot, int chargeToUse) {
		int charge = getMigratedStoredCharge(containerStack, slot);
		int partialCharge = getPartialCharge(containerStack, slot);

		if (partialCharge >= chargeToUse) {
			if (partialCharge == chargeToUse) {
				removePartialCharge(containerStack, slot);
			} else {
				setPartialCharge(containerStack, slot, partialCharge - chargeToUse);
			}
			return true;
		}

		int worth = getSlotWorth(slot);

		if ((long) charge * worth + partialCharge >= chargeToUse) {
			long additionalPartialChargeNeeded = (long) chargeToUse - partialCharge;
			int actualChargeToRemove = (int) (additionalPartialChargeNeeded / worth + (additionalPartialChargeNeeded % worth > 0 ? 1 : 0));
			int partialChargeToAdd = (int) ((long) actualChargeToRemove * worth - chargeToUse);
			if (actualChargeToRemove == charge && removeSlotWhenEmpty(slot)) {
				removeSlot(containerStack, slot);
			} else {
				extractStoredCharge(containerStack, slot, actualChargeToRemove);
			}

			int newPartialCharge = partialCharge + partialChargeToAdd;
			if (newPartialCharge > 0) {
				setPartialCharge(containerStack, slot, newPartialCharge);
			} else {
				removePartialCharge(containerStack, slot);
			}
			return true;
		}

		return false;
	}

	protected boolean addItemToContainer(ItemStack container, Item item, int chargeToAdd) {
		ItemStack stack = new ItemStack(item);
		stack.setCount(chargeToAdd);
		return getFromHandler(container, handler -> handler.insertItemOrAddIntoNewSlotIfNoStackMatches(stack)).isEmpty();
	}

	public boolean removeItemFromInternalStorage(ItemStack stack, int slot, int quantityToRemove, boolean simulate, Player player) {
		if (player.isCreative()) {
			return true;
		}

		return getFromHandler(stack, handler -> handler.extractItemAndRemoveSlotIfEmpty(slot, quantityToRemove, simulate)).getCount() == quantityToRemove;
	}
}

package reliquary.item;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import reliquary.init.ModDataComponents;
import reliquary.reference.Config;
import reliquary.util.RandHelper;
import reliquary.util.TooltipBuilder;

import javax.annotation.Nullable;

public class DestructionCatalystItem extends ChargeableItem {

	public DestructionCatalystItem() {
		super(new Properties().stacksTo(1).setNoRepair());
	}

	@Override
	protected void addMoreInformation(ItemStack catalyst, @Nullable HolderLookup.Provider registries, TooltipBuilder tooltipBuilder) {
		tooltipBuilder.charge(this, ".tooltip2", getTotalCharge(catalyst));

		if (isEnabled(catalyst)) {
			tooltipBuilder.absorbActive(Items.GUNPOWDER.getName(new ItemStack(Items.GUNPOWDER)).getString());
		} else {
			tooltipBuilder.absorb();
		}
	}

	@Override
	protected boolean hasMoreInformation(ItemStack stack) {
		return true;
	}

	@Override
	public InteractionResult useOn(UseOnContext itemUseContext) {
		Player player = itemUseContext.getPlayer();
		if (player != null && player.isCrouching()) {
			return InteractionResult.PASS;
		}

		ItemStack stack = itemUseContext.getItemInHand();
		if (getTotalCharge(stack) >= gunpowderCost() || (player != null && player.isCreative())) {
			if (doExplosion(itemUseContext.getLevel(), itemUseContext.getClickedPos(), itemUseContext.getClickedFace()) && player != null
					&& !player.isCreative() && !player.level().isClientSide()) {
				useCharge(stack, gunpowderCost());
			}
			return InteractionResult.SUCCESS;
		}
		return InteractionResult.FAIL;
	}

	@Override
	public void inventoryTick(ItemStack catalyst, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 10 != 0) {
			return;
		}

		if (isEnabled(catalyst)) {
			int freeCapacity = Math.max(gunpowderLimit() - getTotalCharge(catalyst), 0) / gunpowderWorth();
			consumeAndCharge(catalyst, 0, player, freeCapacity, 1, 16);
		}
	}

	@Override
	protected boolean isItemValidForContainerSlot(ItemStack containerStack, int slot, ItemStack stack) {
		return slot == 0 && stack.is(Items.GUNPOWDER);
	}

	@Override
	public void addStoredCharge(ItemStack catalyst, int slot, int chargeToAdd, @Nullable ItemStack chargeStack) {
		int currentCharge = getGunpowder(catalyst);
		int updatedCharge = chargeToAdd > 0
				? currentCharge + Math.min(chargeToAdd, Math.max(gunpowderLimit() / gunpowderWorth() - currentCharge, 0))
				: Math.max(currentCharge + chargeToAdd, 0);
		catalyst.set(ModDataComponents.GUNPOWDER, updatedCharge);
	}

	@Override
	public int getStoredCharge(ItemStack containerStack, int slot) {
		return getGunpowder(containerStack);
	}

	@Override
	protected int getSlotWorth(int slot) {
		return slot == 0 ? gunpowderWorth() : 0;
	}

	@Override
	protected int getContainerSlotLimit(int slot) {
		return slot == 0 ? gunpowderLimit() / gunpowderWorth() : 0;
	}

	public static int getGunpowder(ItemStack catalyst) {
		return catalyst.getOrDefault(ModDataComponents.GUNPOWDER, 0);
	}

	private int getExplosionRadius() {
		return Config.COMMON.items.destructionCatalyst.explosionRadius.get();
	}

	private boolean perfectCube() {
		return Config.COMMON.items.destructionCatalyst.perfectCube.get();
	}

	private boolean doExplosion(Level level, BlockPos pos, Direction direction) {
		boolean destroyedSomething = false;
		boolean playOnce = true;
		BlockPos origin = pos;
		if (Boolean.FALSE.equals(Config.COMMON.items.destructionCatalyst.centeredExplosion.get())) {
			origin = pos.relative(direction.getOpposite(), getExplosionRadius());
		}
		for (BlockPos target : BlockPos.betweenClosed(origin.offset(-getExplosionRadius(), -getExplosionRadius(), -getExplosionRadius()),
				origin.offset(getExplosionRadius(), getExplosionRadius(), getExplosionRadius()))) {
			if (!perfectCube()) {
				double distance = origin.distSqr(target);
				if (distance >= getExplosionRadius()) {
					continue;
				}
			}

			// noinspection ConstantConditions
			if (isBreakable(BuiltInRegistries.BLOCK.getKey(level.getBlockState(target).getBlock()).toString())) {
				level.setBlockAndUpdate(target, Blocks.AIR.defaultBlockState());
				if (level.random.nextInt(2) == 0) {
					level.addParticle(ParticleTypes.EXPLOSION, target.getX() + (level.random.nextFloat() - 0.5F),
							target.getY() + (level.random.nextFloat() - 0.5F), target.getZ() + (level.random.nextFloat() - 0.5F), 0.0D, 0.0D, 0.0D);
				}
				destroyedSomething = true;
				if (playOnce) {
					level.playSound(null, target, SoundEvents.GENERIC_EXPLODE.value(), SoundSource.BLOCKS, 4.0F,
							(1.0F + RandHelper.getRandomMinusOneToOne(level.random) * 0.2F) * 0.7F);
					playOnce = false;
				}
			}
		}
		return destroyedSomething;
	}

	private boolean isBreakable(String id) {
		return Config.COMMON.items.destructionCatalyst.mundaneBlocks.get().contains(id);
	}

	private int gunpowderCost() {
		return Config.COMMON.items.destructionCatalyst.gunpowderCost.get();
	}

	private int gunpowderWorth() {
		return Config.COMMON.items.destructionCatalyst.gunpowderWorth.get();
	}

	private int gunpowderLimit() {
		return Config.COMMON.items.destructionCatalyst.gunpowderLimit.get();
	}
}

package reliquary.item.component;

import com.google.common.base.Preconditions;
import net.minecraft.core.NonNullList;
import net.minecraft.core.component.DataComponentType;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.items.IItemHandlerModifiable;

import java.util.function.BiFunction;
import java.util.function.BiPredicate;

public class OversizedComponentItemHandler implements IItemHandlerModifiable {
	protected final ItemStack parent;
	protected final DataComponentType<OversizedItemContainerContents> component;
	protected final int size;
	private final BiFunction<ItemStack, Integer, Integer> getSlotLimit;
	private final BiPredicate<Integer, ItemStack> isItemValid;

	public OversizedComponentItemHandler(ItemStack parent, DataComponentType<OversizedItemContainerContents> component, int size,
			BiFunction<ItemStack, Integer, Integer> getSlotLimit, BiPredicate<Integer, ItemStack> isItemValid) {
		this.parent = parent;
		this.component = component;
		this.size = size;
		this.getSlotLimit = getSlotLimit;
		this.isItemValid = isItemValid;
		Preconditions.checkArgument(size <= OversizedItemContainerContents.MAX_SIZE,
				"The max size of OversizedItemContainerContents is " + OversizedItemContainerContents.MAX_SIZE + " slots.");
	}

	@Override
	public int getSlots() {
		return this.size;
	}

	@Override
	public ItemStack getStackInSlot(int slot) {
		OversizedItemContainerContents contents = this.getContents();
		return this.getStackFromContents(contents, slot);
	}

	public int getCountInSlot(int slot) {
		OversizedItemContainerContents contents = this.getContents();
		return contents.getSlots() > slot ? contents.getCountInSlot(slot) : 0;
	}

	@Override
	public void setStackInSlot(int slot, ItemStack stack) {
		this.validateSlotIndex(slot);
		if (!this.isItemValid(slot, stack)) {
			throw new RuntimeException("Invalid stack " + stack + " for slot " + slot + ")");
		} else {
			OversizedItemContainerContents contents = this.getContents();
			ItemStack existing = this.getStackFromContents(contents, slot);
			if (!ItemStack.matches(stack, existing)) {
				this.updateContents(contents, stack, slot);
			}
		}
	}

	public ItemStack insertItemOrAddIntoNewSlotIfNoStackMatches(ItemStack stack) {
		if (stack.isEmpty()) {
			return ItemStack.EMPTY;
		}

		for (int slot = 0; slot < getSlots(); slot++) {
			if (ItemStack.isSameItemSameComponents(stack, getStackInSlot(slot)) || (isItemValid(slot, stack) && getStackInSlot(slot).isEmpty())) {
				return insertItem(slot, stack, false);
			}
		}

		OversizedItemContainerContents contents = this.getContents();
		int newSlot = this.getSlots();
		NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots() + 1), ItemStack.EMPTY);
		if (!this.isItemValid(newSlot, stack)) {
			return stack;
		}
		contents.copyInto(list);
		int countToAdd = Math.min(stack.getCount(), getSlotLimit(list.size()));
		ItemStack stackToAdd = stack.copyWithCount(countToAdd);
		list.set(newSlot, stackToAdd);
		this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
		this.onContentsChanged(newSlot, ItemStack.EMPTY, stackToAdd);
		return countToAdd == stack.getCount() ? ItemStack.EMPTY : stack.copyWithCount(stack.getCount() - countToAdd);
	}

	public ItemStack extractItemAndRemoveSlotIfEmpty(int slot, int amount, boolean simulate) {
		return extractItemAndRemoveSlotIfEmpty(slot, amount, () -> {
		}, simulate);
	}

	public ItemStack extractItemAndRemoveSlotIfEmpty(int slot, int amount, Runnable onSlotRemoved, boolean simulate) {
		ItemStack stack = this.extractItem(slot, amount, simulate);
		if (!simulate && getStackInSlot(slot).isEmpty()) {
			OversizedItemContainerContents contents = this.getContents();
			NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots()), ItemStack.EMPTY);
			for (int i = 0; i < slot; i++) {
				list.set(i, contents.getSlots() > i ? contents.getStackInSlot(i) : ItemStack.EMPTY);
			}
			for (int i = slot; i < list.size(); i++) {
				list.set(i, contents.getSlots() > i + 1 ? contents.getStackInSlot(i + 1) : ItemStack.EMPTY);
			}
			this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
			this.onContentsChanged(slot, stack, ItemStack.EMPTY);
			onSlotRemoved.run();
		}
		return stack;

	}

	public void removeSlot(int slot) {
		OversizedItemContainerContents contents = this.getContents();
		NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots()), ItemStack.EMPTY);
		for (int i = 0, j = 0; i < size; i++) {
			if (i == slot)
				continue;
			list.set(j++, contents.getSlots() > i ? contents.getStackInSlot(i) : ItemStack.EMPTY);
		}
		this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
	}

	@Override
	public ItemStack insertItem(int slot, ItemStack toInsert, boolean simulate) {
		this.validateSlotIndex(slot);
		if (toInsert.isEmpty()) {
			return ItemStack.EMPTY;
		} else if (!this.isItemValid(slot, toInsert)) {
			return toInsert;
		} else {
			OversizedItemContainerContents contents = this.getContents();
			ItemStack existing = this.getStackFromContents(contents, slot);
			int insertLimit = this.getSlotLimit(slot);
			if (!existing.isEmpty()) {
				if (!ItemStack.isSameItemSameComponents(toInsert, existing)) {
					return toInsert;
				}

				insertLimit -= existing.getCount();
			}

			if (insertLimit <= 0) {
				return toInsert;
			} else {
				int inserted = Math.min(insertLimit, toInsert.getCount());
				if (!simulate) {
					this.updateContents(contents, toInsert.copyWithCount(existing.getCount() + inserted), slot);
				}

				return toInsert.copyWithCount(toInsert.getCount() - inserted);
			}
		}
	}

	@Override
	public ItemStack extractItem(int slot, int amount, boolean simulate) {
		this.validateSlotIndex(slot);
		if (amount == 0) {
			return ItemStack.EMPTY;
		} else {
			OversizedItemContainerContents contents = this.getContents();
			ItemStack existing = this.getStackFromContents(contents, slot);
			if (existing.isEmpty()) {
				return ItemStack.EMPTY;
			} else {
				int toExtract = Math.min(Math.min(amount, existing.getMaxStackSize()), existing.getCount());
				if (!simulate) {
					this.updateContents(contents, existing.copyWithCount(existing.getCount() - toExtract), slot);
				}

				return existing.copyWithCount(toExtract);
			}
		}
	}

	@Override
	public int getSlotLimit(int slot) {
		return getSlotLimit.apply(parent, slot);
	}

	@Override
	public boolean isItemValid(int slot, ItemStack stack) {
		return stack.isEmpty() || isItemValid.test(slot, stack) && stack.getItem().canFitInsideContainerItems();
	}

	protected void onContentsChanged(int slot, ItemStack oldStack, ItemStack newStack) {
	}

	protected OversizedItemContainerContents getContents() {
		if (this.parent.has(this.component)) {
			return this.parent.get(this.component);
		}

		return OversizedItemContainerContents.fromSize(size);
	}

	protected ItemStack getStackFromContents(OversizedItemContainerContents contents, int slot) {
		this.validateSlotIndex(slot);
		return contents.getSlots() <= slot ? ItemStack.EMPTY : contents.getStackInSlot(slot);
	}

	protected void updateContents(OversizedItemContainerContents contents, ItemStack stack, int slot) {
		this.validateSlotIndex(slot);
		NonNullList<ItemStack> list = NonNullList.withSize(Math.max(contents.getSlots(), this.getSlots()), ItemStack.EMPTY);
		contents.copyInto(list);
		ItemStack oldStack = list.get(slot);
		list.set(slot, stack);
		this.parent.set(this.component, OversizedItemContainerContents.fromItems(list));
		this.onContentsChanged(slot, oldStack, stack);
	}

	protected final void validateSlotIndex(int slot) {
		if (slot < 0 || slot >= this.getSlots()) {
			throw new RuntimeException("Slot " + slot + " not in valid range - [0," + this.getSlots() + ")");
		}
	}
}

package reliquary.item.component;

import com.google.common.collect.Iterables;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.NonNullList;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import reliquary.util.CodecHelper;

import java.util.ArrayList;
import java.util.List;
import java.util.OptionalInt;
import java.util.stream.Stream;

public final class OversizedItemContainerContents {
	private static final int NO_SLOT = -1;
	public static final int MAX_SIZE = 256;
	public static final OversizedItemContainerContents EMPTY = new OversizedItemContainerContents(NonNullList.create());
	public static final Codec<OversizedItemContainerContents> CODEC;
	public static final StreamCodec<RegistryFriendlyByteBuf, OversizedItemContainerContents> STREAM_CODEC;
	private final NonNullList<ItemStack> items;
	private final int hashCode;

	private OversizedItemContainerContents(NonNullList<ItemStack> items) {
		if (items.size() > MAX_SIZE) {
			throw new IllegalArgumentException("Got " + items.size() + " items, but maximum is " + MAX_SIZE);
		} else {
			this.items = items;
			this.hashCode = ItemStack.hashStackList(items);
		}
	}

	private OversizedItemContainerContents(int p_331689_) {
		this(NonNullList.withSize(p_331689_, ItemStack.EMPTY));
	}

	private OversizedItemContainerContents(List<ItemStack> items) {
		this(items.size());

		for (int i = 0; i < items.size(); ++i) {
			this.items.set(i, items.get(i));
		}

	}

	private static OversizedItemContainerContents fromSlots(List<Slot> slots) {
		OptionalInt maxIndex = slots.stream().mapToInt(Slot::index).max();
		if (maxIndex.isEmpty()) {
			return EMPTY;
		} else {
			OversizedItemContainerContents contents = new OversizedItemContainerContents(maxIndex.getAsInt() + 1);
			slots.forEach((slot) -> contents.items.set(slot.index(), slot.item()));
			return contents;
		}
	}

	public static OversizedItemContainerContents fromSize(int size) {
		return new OversizedItemContainerContents(size);
	}

	public static OversizedItemContainerContents fromItems(List<ItemStack> p_340879_) {
		int i = findLastNonEmptySlot(p_340879_);
		if (i == NO_SLOT) {
			return EMPTY;
		} else {
			OversizedItemContainerContents contents = new OversizedItemContainerContents(i + 1);

			for (int index = 0; index <= i; ++index) {
				contents.items.set(index, p_340879_.get(index).copy());
			}

			return contents;
		}
	}

	private static int findLastNonEmptySlot(List<ItemStack> items) {
		for (int i = items.size() - 1; i >= 0; --i) {
			if (!items.get(i).isEmpty()) {
				return i;
			}
		}

		return NO_SLOT;
	}

	private List<Slot> asSlots() {
		List<Slot> list = new ArrayList<>();

		for (int i = 0; i < this.items.size(); ++i) {
			ItemStack itemstack = this.items.get(i);
			if (!itemstack.isEmpty()) {
				list.add(new Slot(i, itemstack));
			}
		}

		return list;
	}

	public void copyInto(NonNullList<ItemStack> p_330513_) {
		for (int i = 0; i < p_330513_.size(); ++i) {
			ItemStack itemstack = i < this.items.size() ? this.items.get(i) : ItemStack.EMPTY;
			p_330513_.set(i, itemstack.copy());
		}

	}

	public ItemStack copyOne() {
		return this.items.isEmpty() ? ItemStack.EMPTY : this.items.getFirst().copy();
	}

	public Stream<ItemStack> stream() {
		return this.items.stream().map(ItemStack::copy);
	}

	public Stream<ItemStack> nonEmptyStream() {
		return this.items.stream().filter((item) -> !item.isEmpty()).map(ItemStack::copy);
	}

	public Iterable<ItemStack> nonEmptyItems() {
		return Iterables.filter(this.items, item -> !item.isEmpty());
	}

	public Iterable<ItemStack> nonEmptyItemsCopy() {
		return Iterables.transform(this.nonEmptyItems(), ItemStack::copy);
	}

	public boolean equals(Object other) {
		if (this == other) {
			return true;
		} else {
			if (other instanceof OversizedItemContainerContents contents) {
				return ItemStack.listMatches(this.items, contents.items);
			}

			return false;
		}
	}

	public int hashCode() {
		return this.hashCode;
	}

	public int getSlots() {
		return this.items.size();
	}

	public ItemStack getStackInSlot(int slot) {
		this.validateSlotIndex(slot);
		return this.items.get(slot).copy();
	}

	public int getCountInSlot(int slot) {
		this.validateSlotIndex(slot);
		return this.items.get(slot).getCount();
	}

	public Item getStackInSlotItem(int slot) {
		this.validateSlotIndex(slot);
		return this.items.get(slot).getItem();
	}

	private void validateSlotIndex(int slot) {
		if (slot < 0 || slot >= this.getSlots()) {
			throw new UnsupportedOperationException("Slot " + slot + " not in valid range - [0," + this.getSlots() + ")");
		}
	}

	static {
		CODEC = Slot.CODEC.sizeLimitedListOf(MAX_SIZE).xmap(OversizedItemContainerContents::fromSlots, OversizedItemContainerContents::asSlots);
		STREAM_CODEC = ItemStack.OPTIONAL_STREAM_CODEC.apply(ByteBufCodecs.list(MAX_SIZE)).map(OversizedItemContainerContents::new,
				(contents) -> contents.items);
	}

	record Slot(int index, ItemStack item) {
		public static final Codec<Slot> CODEC = RecordCodecBuilder
				.create((instance) -> instance
						.group(Codec.intRange(0, 255).fieldOf("slot").forGetter(Slot::index),
								CodecHelper.OVERSIZED_ITEM_STACK_CODEC.orElse(ItemStack.EMPTY).fieldOf("item").forGetter(Slot::item))
						.apply(instance, Slot::new));
	}
}

package reliquary.util;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.component.DataComponentPatch;
import net.minecraft.world.item.ItemStack;

import java.util.Set;

public class CodecHelper {
	public static final Codec<ItemStack> OVERSIZED_ITEM_STACK_CODEC = Codec
			.lazyInitialized(
					() -> RecordCodecBuilder
							.create(instance -> instance
									.group(ItemStack.ITEM_NON_AIR_CODEC.fieldOf("id").forGetter(ItemStack::getItemHolder),
											Codec.INT.fieldOf("count").orElse(1).forGetter(ItemStack::getCount), DataComponentPatch.CODEC
													.optionalFieldOf("components", DataComponentPatch.EMPTY).forGetter(ItemStack::getComponentsPatch))
									.apply(instance, ItemStack::new)));

	public static <T> Codec<Set<T>> setOf(Codec<T> elementCodec) {
		return new SetCodec<>(elementCodec);
	}
}
